def parent(i):
    m=i.get('metadata') or {}
    return i.get('parent') or m.get('parent')
active=[i for i in items if i.get('status')=='active']
def held(i):
    if i.get('owner') in live: return 'owner'
    if i['id'] in rmrefs: return 'roadmap_refs'
    for r in (i.get('task_refs') or []) :
        if r in live: return 'task_refs'
    return None
direct={i['id']:held(i) for i in active if held(i)}
# ancestors of directly-held rows (any status held row, walk up)
anc=set()
for i in items:
    if held(i):
        p=parent(i)
        while p and p in by:
            anc.add(p); p=parent(by[p])
