for i in active:
    if i['id'] not in direct and i['id'] in anc: print('   anc:',i['id'])
print('LEFTOVER/orphan candidates:',len(orph))
for o in orph: print('   *',o,'owner=',repr(by[o].get('owner')))
EOF

